inventory = []
for fid, title, actors, actions, paths, tables, status in features:
    inventory.append(dict(id=fid, name=title, actors=actors, actions=actions, source_paths=paths, tables=tables, evidence_status=status))
source_map = []
for path in sorted((ROOT / 'app/src').rglob('*.php')):
    content = path.read_bytes()
    lines = content.decode('utf-8-sig').splitlines()
    methods = []
    for n, line in enumerate(lines, 1):
        match = re.search(r'\b(?:(public|protected|private)\s+)?(?:static\s+)?function\s+(\w+)\s*\(', line)
        if match:
            methods.append(dict(name=match.group(2), visibility=match.group(1), line=n))
    source_map.append(dict(path=path.relative_to(ROOT).as_posix(), sha256=hashlib.sha256(content).hexdigest(), lines=len(lines), review='full source read', methods=methods))
(OUT / 'backend-feature-notes.json').write_text(json.dumps(dict(audit_date='2026-10-17', timezone='Asia/Manila', limits='Source evidence, metadata and stated synthetic fixtures only; no production-row reads or state mutations.', features=inventory, source_coverage=source_map), indent=2) + '\n', encoding='utf-8')
print(json.dumps(dict(features=len(features), php_source_files=len(source_map), methods=sum(len(s['methods']) for s in source_map))))
